import assert from 'node:assert/strict';
import test from 'node:test';
import { randomUUID } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { operationsFixture } from './operations-fixture.ts';
import { communityProfilesContract } from '../src/modules/community-profiles.ts';
import { businessContract } from '../src/modules/business.ts';
import { upgradeToCurrent } from './migration-upgrade.ts';

async function fixture(throughSchema?:number){const f=await operationsFixture({throughSchema});try{if(throughSchema===undefined||throughSchema>=148)for(const role of [f.managerRole,f.staffRole])for(const cap of ['profiles.view','profiles.edit'])await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow')",[f.a,role,cap]);const definition={content:{en:{displayName:'Robotics builder',headline:'Build and learn',bio:'PRIVATE draft biography <script>literal text only</script>'},fr:{displayName:'Équipe robotique',headline:'Apprendre',bio:'PRIVATE biographie'},'zh-CN':{displayName:'机器人学员',headline:'学习与创造',bio:'PRIVATE 简介'}},links:{github:'https://github.com/kavosh-ai?tab=repositories#top',linkedin:'https://linkedin.com/in/robotics-teacher/?trk=share#first'},archived:false},input={anchor:{kind:'person',id:f.actors.staff.person},definition,reason:'PRIVATE draft edit reason'},create=(body:unknown=input,as='master',key?:string)=>f.request('community/profiles',body,as,{key});return {...f,definition,input,create};}catch(error){await f.pg.close();throw error;}}
type F=Awaited<ReturnType<typeof fixture>>;
function check(name:string,run:(f:F)=>Promise<void>){test(name,async()=>{const f=await fixture();try{await run(f);}finally{await f.pg.close();}});}
async function moderationAccess(f:F){for(const role of [f.staffRole,f.managerRole])for(const cap of ['profile-moderation.view','profile-moderation.edit'])await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow') ON CONFLICT DO NOTHING",[f.a,role,cap]);}
const restriction=(expectedVersion=0,expectedProfileVersion=1,restricted=true)=>({expectedVersion,expectedProfileVersion,restricted,reason:'PRIVATE_MODERATION reviewed safety concern'});
check('profile moderation is independent of edited content and only reviewed restoration reopens self service without publishing',async f=>{
 await selfAccess(f);const key=randomUUID(),original={expectedVersion:0,definition:f.definition},created=await f.request('me/community-profile',original,'staff',{key});assert.equal(created.response.status,201);const id=created.body.data.id,path='community/profiles/'+id+'/moderation';assert.deepEqual((await f.request(path)).body.data,{profileId:id,profileVersion:1,version:0,restricted:false,publicationEnabled:false});const locked=await f.request(path,restriction());assert.equal(locked.response.status,200,JSON.stringify({body:locked.body,failures:f.metrics.queryFailures}));const own=await f.request('me/community-profile',undefined,'staff');assert.equal(own.body.data.selfEditingAllowed,false);assert.deepEqual(own.body.data.moderation,{version:1,restricted:true});assert.doesNotMatch(JSON.stringify(own.body),/PRIVATE_MODERATION|source_basis|approvalId|changedBy/);assert.equal((await f.request('me/community-profile',original,'staff',{key})).response.status,403);assert.equal((await f.request('me/community-profile',{expectedVersion:1,definition:{...f.definition,archived:true}},'staff')).response.status,403);
 for(const cap of ['profiles.view','profiles.edit'])await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow')",[f.a,f.staffRole,cap]);const generic=await f.request('community/profiles/'+id+'/change',{expectedVersion:1,definition:f.definition},'staff');assert.equal(generic.response.status,403,JSON.stringify(generic.body));const fixed=await f.request('community/profiles/'+id+'/change',{expectedVersion:1,definition:{...f.definition,content:{en:{displayName:'Remediated robotics profile'}}},reason:'PRIVATE administrative remediation'});assert.equal(fixed.response.status,200);assert.equal((await f.request(path)).body.data.restricted,true);assert.equal((await f.request(path,restriction(1,1,false))).response.status,409);assert.equal((await f.request(path,restriction(1,2,false))).response.status,200);assert.equal((await f.request('me/community-profile',undefined,'staff')).body.data.selfEditingAllowed,true);assert.equal((await f.request('me/community-profile',{expectedVersion:2,definition:f.definition},'staff')).response.status,200);assert.deepEqual((await f.request('me/community-profile',original,'staff',{key})).body,created.body);
 const h=await f.request(path+'/history?limit=1');assert.equal(h.body.data.length,1);assert.equal(h.body.nextVersion,1);assert.equal((await f.request(path+'/history?afterVersion=1')).body.data[0].restricted,false);assert.equal((await f.pg.query('SELECT * FROM public.profile_moderation_changes')).rows.length,2);const audit=(await f.pg.query("SELECT changes FROM public.audit_events WHERE action='community-profile.moderate'")).rows;assert.equal(audit.length,2);assert.ok(audit.every((r:any)=>r.changes.severity==='critical'&&r.changes.privateContentRedacted));assert.doesNotMatch(JSON.stringify(audit),/PRIVATE_MODERATION|Robotics builder|biography/);const events=(await f.pg.query("SELECT projection FROM public.automation_event_sources WHERE event_type LIKE 'community-profile.moderate%' OR approval_id IN(SELECT approval_id FROM public.profile_moderation_changes)")).rows;assert.ok(events.length>0);assert.doesNotMatch(JSON.stringify(events),/PRIVATE_MODERATION|biography/);
});
check('profile moderation needs upper human review and bots may propose but cannot decide or change state directly',async f=>{
 const created=await f.create();await moderationAccess(f);const path='community/profiles/'+created.body.data.id+'/moderation',p=await f.request(path,restriction(),'staff');assert.equal(p.response.status,202,JSON.stringify(p.body));assert.equal((await f.request(path)).body.data.restricted,false);assert.equal((await f.approve(p.body.approval.id,'staff')).response.status,403);assert.equal((await f.approve(p.body.approval.id,'manager')).response.status,200);const bot=await f.request(path,restriction(1,1,false),'bot');assert.equal(bot.response.status,202,JSON.stringify(bot.body));assert.equal((await f.request(path)).body.data.restricted,true);assert.equal((await f.approve(bot.body.approval.id,'bot')).response.status,403);assert.equal((await f.approve(bot.body.approval.id)).response.status,200);assert.equal((await f.request(path)).body.data.restricted,false);
});
check('pending profile moderation becomes stale after content or owner changes without silently restricting another edition',async f=>{
 await selfAccess(f);await moderationAccess(f);const created=await f.create(),id=created.body.data.id,path='community/profiles/'+id+'/moderation',p=await f.request(path,restriction(),'staff');assert.equal(p.response.status,202);assert.equal((await f.request('me/community-profile',{expectedVersion:1,definition:f.definition},'staff')).response.status,200);const stale=await f.approve(p.body.approval.id);assert.equal(stale.response.status,409,JSON.stringify(stale.body));assert.equal(stale.body.approval.status,'stale');assert.equal((await f.pg.query('SELECT * FROM public.profile_moderation_heads')).rows.length,0);const again=await f.request(path,restriction(0,2),'staff');assert.equal(again.response.status,202);await f.pg.query('UPDATE public.people SET hub_id=$2 WHERE id=$1',[f.actors.staff.person,f.otherHub]);assert.equal((await f.approve(again.body.approval.id)).response.status,409);assert.equal((await f.pg.query('SELECT * FROM public.profile_moderation_changes')).rows.length,0);
});
check('profile moderation private history follows current person hub school and explicit-denial scopes not profile or self-profile rights',async f=>{
 const created=await f.create(),id=created.body.data.id,path='community/profiles/'+id+'/moderation';assert.equal((await f.request(path,restriction())).response.status,200);for(const suffix of ['','/history']){assert.equal((await f.request(path+suffix,undefined,'staff')).response.status,404);assert.equal((await f.request(path+suffix,undefined,'peer')).response.status,404);assert.equal((await f.request(path+suffix,undefined,'foreignMaster',{academy:f.b})).response.status,404);}await moderationAccess(f);assert.equal((await f.request(path+'/history',undefined,'manager')).response.status,200);const denied=await f.request('roles',{name:'Synthetic restricted moderation viewer',permissions:[{capability:'profile-moderation.view',effect:'deny'}]});assert.equal(denied.response.status,201);const assignment=randomUUID();await f.pg.query('INSERT INTO public.role_assignments(academy_id,id,person_id,role_id,all_hubs) VALUES($1,$2,$3,$4,false)',[f.a,assignment,f.actors.manager.person,denied.body.data.id]);await f.pg.query('INSERT INTO public.assignment_people VALUES($1,$2,$3)',[f.a,assignment,f.actors.staff.person]);assert.equal((await f.request(path+'/history',undefined,'manager')).response.status,404);assert.equal((await f.request(path,restriction(1,1,false),'manager')).response.status,404);
 for(const input of [{...restriction(),restricted:'yes'},{...restriction(),expectedVersion:-1},{...restriction(),expectedProfileVersion:0},{...restriction(),reason:'bad\nreason'},{...restriction(),visibility:'public'}])assert.equal((await f.request(path,input)).response.status,400);assert.equal((await f.request(path+'?x=1',restriction())).response.status,400);assert.equal((await f.request(path+'/history?limit=1&limit=2')).response.status,400);
});
check('profile restriction remains available in read-only schools but restoration and other profile writes remain blocked',async f=>{
 await moderationAccess(f);const created=await f.create(),path='community/profiles/'+created.body.data.id+'/moderation';await f.pg.query("UPDATE public.academies SET status='read_only' WHERE id=$1",[f.a]);const pending=await f.request(path,restriction(),'staff');assert.equal(pending.response.status,202,JSON.stringify(pending.body));assert.equal((await f.approve(pending.body.approval.id)).response.status,200);assert.equal((await f.request(path)).body.data.restricted,true);assert.equal((await f.request(path,restriction(1,1,false))).response.status,403);assert.equal((await f.request('community/profiles/'+created.body.data.id+'/change',{expectedVersion:1,definition:f.definition})).response.status,403);
});
check('profile moderation failed audit is atomic and same-key retry never leaves unreviewed state or duplicate history',async f=>{
 const created=await f.create(),path='community/profiles/'+created.body.data.id+'/moderation',key=randomUUID();await f.pg.exec('REVOKE INSERT ON public.outbox_events FROM kavosh_runtime');try{assert.equal((await f.request(path,restriction(),'master',{key})).response.status,503);}finally{await f.pg.exec('GRANT INSERT ON public.outbox_events TO kavosh_runtime');}assert.equal((await f.pg.query('SELECT * FROM public.profile_moderation_changes')).rows.length,0);assert.equal((await f.pg.query('SELECT * FROM public.profile_moderation_heads')).rows.length,0);const retry=await f.request(path,restriction(),'master',{key});assert.equal(retry.response.status,200,JSON.stringify({body:retry.body,failures:f.metrics.queryFailures}));assert.deepEqual((await f.request(path,restriction(),'master',{key})).body,retry.body);assert.equal((await f.pg.query('SELECT * FROM public.profile_moderation_changes')).rows.length,1);
});
check('native profile moderation immutable head tenant and exact payload guards prevent direct bypass',async f=>{
 await moderationAccess(f);const created=await f.create(),id=created.body.data.id,path='community/profiles/'+id+'/moderation',p=await f.request(path,restriction(),'staff');assert.equal(p.response.status,202);await f.pg.exec('BEGIN;SET LOCAL ROLE kavosh_runtime');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);await assert.rejects(f.pg.query("INSERT INTO public.profile_moderation_changes(academy_id,profile_id,version,before_restricted,restricted,source_basis,changed_by,approval_id,reason) SELECT academy_id,target_id,1,false,true,review_context,$2,id,'FORGED private reason' FROM public.approval_requests WHERE id=$1",[p.body.approval.id,f.actors.master.person]),/PROFILE_MODERATION_EXACT_REVIEW_REQUIRED/);}finally{await f.pg.exec('ROLLBACK');}assert.equal((await f.approve(p.body.approval.id)).response.status,200);
 await f.pg.exec('BEGIN');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);await assert.rejects(f.pg.query('UPDATE public.community_profiles SET version=version+1,changed_by=$2 WHERE id=$1',[id,f.actors.staff.person]),/PROFILE_SELF_EDIT_RESTRICTED/);}finally{await f.pg.exec('ROLLBACK');}for(const sql of ['DELETE FROM public.profile_moderation_changes','UPDATE public.profile_moderation_changes SET restricted=false','DELETE FROM public.profile_moderation_heads'])await assert.rejects(f.pg.exec(sql),/PROFILE_MODERATION_/);await f.pg.exec('SET ROLE kavosh_runtime');try{await f.pg.query("SELECT set_config('app.academy_id',$1,false)",[f.b]);assert.equal((await f.pg.query('SELECT * FROM public.profile_moderation_heads')).rows.length,0);assert.equal((await f.pg.query('SELECT public.profile_moderation_state($1) s',[id])).rows[0].s,null);}finally{await f.pg.exec('RESET ROLE');}
});
test('native profile moderation competing requests have one complete restriction winner',{skip:!process.env.TEST_DATABASE_URL},async()=>{
 const f=await fixture();try{const created=await f.create(),path='community/profiles/'+created.body.data.id+'/moderation',out=await Promise.all([f.request(path,restriction()),f.request(path,restriction())]);assert.deepEqual(out.map(r=>r.response.status).sort(),[200,409],JSON.stringify(out.map(r=>r.body)));assert.equal((await f.pg.query('SELECT * FROM public.profile_moderation_changes')).rows.length,1);assert.equal((await f.pg.query('SELECT * FROM public.profile_moderation_heads')).rows.length,1);}finally{await f.pg.close();}
});
test('profile moderation actual191to192 upgrade preserves profiles old receipts roles and source helpers with no invented restrictions',async()=>{
 const f=await fixture(191);try{const key=randomUUID(),created=await f.create(f.input,'master',key);assert.equal(created.response.status,201);const snapshot=async()=>{const rows=[];for(const table of ['people','roles','role_permissions','role_assignments','community_profiles','community_profile_revisions','approval_requests','audit_events','outbox_events','request_keys'])rows.push((await f.pg.query('SELECT to_jsonb(t) r FROM public.'+table+' t ORDER BY to_jsonb(t)::text')).rows);return rows;},before=await snapshot(),helpers="SELECT oid,proowner,proacl FROM pg_proc WHERE oid=ANY(ARRAY['public.community_profile_owner(text,uuid,boolean)'::regprocedure,'public.guard_community_profile()'::regprocedure,'public.require_community_profile_receipt()'::regprocedure,'public.capture_automation_event()'::regprocedure]) ORDER BY oid",identity=(await f.pg.query(helpers)).rows;await f.pg.exec(await readFile(new URL('../db/migrations/192_profile_moderation.sql',import.meta.url),'utf8'));assert.deepEqual(await snapshot(),before);assert.deepEqual((await f.pg.query(helpers)).rows,identity);assert.equal((await f.pg.query('SELECT public.schema_revision() n')).rows[0].n,192);await upgradeToCurrent(f.pg);assert.deepEqual((await f.create(f.input,'master',key)).body,created.body);assert.equal((await f.pg.query('SELECT * FROM public.profile_moderation_changes')).rows.length,0);assert.equal((await f.request('community/profiles/'+created.body.data.id+'/moderation')).body.data.version,0);}finally{await f.pg.close();}
});

test('native concurrent self edit and profile restriction choose one coherent reviewed source without a lost moderation decision',{skip:!process.env.TEST_DATABASE_URL},async()=>{
 const f=await fixture();try{await selfAccess(f);const created=await f.request('me/community-profile',{expectedVersion:0,definition:f.definition},'staff');assert.equal(created.response.status,201);const id=created.body.data.id,[edit,moderated]=await Promise.all([f.request('me/community-profile',{expectedVersion:1,definition:{...f.definition,content:{en:{displayName:'Concurrent self correction'}}}},'staff'),f.request('community/profiles/'+id+'/moderation',restriction())]);assert.ok(edit.response.status===200&&moderated.response.status===409||edit.response.status===403&&moderated.response.status===200,JSON.stringify({edit:edit.body,moderated:moderated.body,failures:f.metrics.queryFailures}));const own=(await f.request('me/community-profile',undefined,'staff')).body.data;assert.equal(own.moderation.restricted,moderated.response.status===200);assert.equal(own.version,edit.response.status===200?2:1);assert.equal((await f.pg.query('SELECT * FROM public.profile_moderation_changes')).rows.length,moderated.response.status===200?1:0);}finally{await f.pg.close();}
});

check('native profile moderation cannot mark an approval applied without its exact effect or commit state without critical audit',async f=>{
 await moderationAccess(f);const created=await f.create(),path='community/profiles/'+created.body.data.id+'/moderation',pending=await f.request(path,restriction(),'staff');assert.equal(pending.response.status,202);const approvalId=pending.body.approval.id,mark=async()=>f.pg.query("UPDATE public.approval_requests SET status='applied',version=version+1,reviewer_id=$2,reason='Synthetic native review',decided_at=now() WHERE id=$1",[approvalId,f.actors.master.person]);await f.pg.exec('BEGIN;SET LOCAL ROLE kavosh_runtime');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);await mark();await assert.rejects(f.pg.exec('COMMIT'),/PROFILE_MODERATION_EFFECT_REQUIRED/);}finally{await f.pg.exec('ROLLBACK');}
 await f.pg.exec('BEGIN;SET LOCAL ROLE kavosh_runtime');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);await f.pg.query("INSERT INTO public.profile_moderation_changes(academy_id,profile_id,version,before_restricted,restricted,source_basis,changed_by,approval_id,reason) SELECT academy_id,target_id,1,false,true,review_context,$2,id,payload->>'reason' FROM public.approval_requests WHERE id=$1",[approvalId,f.actors.master.person]);await f.pg.query('INSERT INTO public.profile_moderation_heads(academy_id,profile_id,version) VALUES($1,$2,1)',[f.a,created.body.data.id]);await mark();await assert.rejects(f.pg.exec('COMMIT'),/PROFILE_MODERATION_EFFECT_AUDIT_REQUIRED/);}finally{await f.pg.exec('ROLLBACK');}assert.equal((await f.pg.query('SELECT * FROM public.profile_moderation_heads')).rows.length,0);assert.equal((await f.pg.query('SELECT status FROM public.approval_requests WHERE id=$1',[approvalId])).rows[0].status,'pending');assert.equal((await f.approve(approvalId)).response.status,200);
});
check('school-wide profile moderation cannot be promoted from a hub grant or a finite bot credential',async f=>{
 await moderationAccess(f);const school=await f.create({...f.input,anchor:{kind:'academy'}});assert.equal(school.response.status,201);const path='community/profiles/'+school.body.data.id+'/moderation';assert.equal((await f.request(path,restriction(),'manager')).response.status,404);assert.equal((await f.request(path,restriction())).response.status,200);for(const cap of ['profile-moderation.view','profile-moderation.edit'])await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow')",[f.a,f.policyRole,cap]);await f.pg.query('UPDATE auth_private.credentials SET all_hubs=false WHERE id=$1',[f.credential]);await f.pg.query('INSERT INTO auth_private.credential_hubs VALUES($1,$2,$3)',[f.credential,f.a,f.hub]);assert.equal((await f.request(path,undefined,'bot')).response.status,404);assert.equal((await f.request(path,restriction(1,1,false),'bot')).response.status,404);assert.equal((await f.request(path)).body.data.restricted,true);assert.equal((await f.request('community/profiles/'+randomUUID()+'/moderation',restriction())).response.status,404);
});

async function selfAccess(f:F,caps=['self-profiles.view','self-profiles.edit']){
 await f.pg.query("DELETE FROM public.role_permissions WHERE role_id=$1 AND capability IN('profiles.view','profiles.edit')",[f.staffRole]);for(const cap of caps)await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,$3,'allow')",[f.a,f.staffRole,cap]);
}
check('self profile editing requires only own feature rights and retains exact retries immutable history and no automatic publication',async f=>{
 await selfAccess(f);const path='me/community-profile',key=randomUUID(),input={expectedVersion:0,definition:f.definition};const before=(await f.pg.query('SELECT id,name,email FROM public.people ORDER BY id')).rows;assert.equal((await f.request(path,undefined,'staff')).body.data,null);const created=await f.request(path,input,'staff',{key});assert.equal(created.response.status,201,JSON.stringify({body:created.body,failures:f.metrics.queryFailures}));assert.equal(created.body.data.version,1);assert.equal(created.body.data.publiclyPublished,false);assert.equal(created.body.data.selfOnly,true);assert.equal(created.body.data.definition.links.github,'https://github.com/kavosh-ai');assert.equal(created.body.data.definition.content.en.bio,f.definition.content.en.bio);assert.deepEqual((await f.request(path,input,'staff',{key})).body,created.body);const read=await f.request(path,undefined,'staff');assert.equal(read.response.status,200);assert.equal(read.body.data.id,created.body.data.id);assert.equal((await f.request('community/profiles/'+created.body.data.id,undefined,'staff')).response.status,404);assert.equal((await f.request('community/profiles',undefined,'staff')).response.status,403);
 const changed=await f.request(path,{expectedVersion:1,definition:{...f.definition,content:{en:{displayName:'Own robotics profile'}}}},'staff');assert.equal(changed.response.status,200,JSON.stringify(changed.body));assert.equal(changed.body.data.version,2);assert.deepEqual((await f.request(path,input,'staff',{key})).body,created.body);assert.equal((await f.request(path,{expectedVersion:1,definition:f.definition},'staff')).response.status,409);assert.equal((await f.request(path,{expectedVersion:2,definition:{...f.definition,archived:true}},'staff')).response.status,200);assert.equal((await f.pg.query('SELECT * FROM public.community_profile_revisions')).rows.length,3);assert.deepEqual((await f.pg.query('SELECT id,name,email FROM public.people ORDER BY id')).rows,before);
 const audit=(await f.pg.query("SELECT changes FROM public.audit_events WHERE action LIKE 'community-profile.%'")).rows;assert.equal(audit.length,3);assert.doesNotMatch(JSON.stringify(audit),/PRIVATE|biography|Robotics builder/);
});
