 await selfAccess(f);const saved=await f.create();assert.equal(saved.response.status,201);const other=await f.create({...f.input,anchor:{kind:'person',id:f.actors.peer.person}});assert.equal(other.response.status,201);const own=await f.request('me/community-profile',undefined,'staff');assert.equal(own.body.data.id,saved.body.data.id);assert.doesNotMatch(JSON.stringify(own.body),/PRIVATE draft edit reason|changed_by|owner_snapshot|changed_at|reason|person_id|auth_user_id/);
 for(const extra of [{personId:f.actors.peer.person},{anchor:{kind:'person',id:f.actors.peer.person}},{profileId:other.body.data.id},{reason:'PRIVATE requested admin note'},{academyId:f.b},{publiclyPublished:true},{visibility:'public'}])assert.equal((await f.request('me/community-profile',{expectedVersion:1,definition:f.definition,...extra},'staff')).response.status,400);
 for(const path of ['me/community-profile?personId='+f.actors.peer.person,'me/community-profile?limit=1&limit=2','me/community-profile/history','me/community-profile/'+other.body.data.id])assert.ok([400,404].includes((await f.request(path,undefined,'staff')).response.status));assert.equal((await f.request('me/community-profile',{expectedVersion:1,definition:{...f.definition,visibility:'public'}},'staff')).response.status,400);assert.equal((await f.pg.query('SELECT * FROM public.community_profile_revisions')).rows.length,2);assert.equal((await f.request('me/community-profile',undefined,'foreignMaster',{academy:f.a})).response.status,401);assert.equal((await f.request('me/community-profile',undefined,'staff',{academy:f.b})).response.status,401);
