check('an unresolved native owner result hides summaries and details instead of treating missing ownership as an empty allowed scope',async f=>{
 const r=await f.create();assert.equal(r.response.status,201);const original=(await f.pg.query<{definition:string}>("SELECT pg_get_functiondef('public.community_profile_owner(text,uuid,boolean)'::regprocedure) definition")).rows[0].definition;
 // Isolated adverse-result injection,not an assertion that production owners
 // are orphaned or that runtime callers can replace this native function.
 await f.pg.exec("CREATE OR REPLACE FUNCTION public.community_profile_owner(p_kind text,p_id uuid,p_lock boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RETURN NULL;END $$");try{const list=await f.request('community/profiles');assert.equal(list.response.status,200);assert.deepEqual(list.body.data,[]);assert.equal(list.body.nextCursor,null);assert.equal((await f.request('community/profiles/'+r.body.data.id)).response.status,404);}finally{await f.pg.exec(original);}assert.equal((await f.request('community/profiles/'+r.body.data.id)).response.status,200);
});
check('profile definitions and native validation reject forged publication fields,unsafe link hosts,credentials and unsupported locations',async f=>{
 for(const links of [{github:'javascript:alert(1)',linkedin:null},{github:'https://github.com.evil.test/name',linkedin:null},{github:'https://user:secret@github.com/name',linkedin:null},{github:'https://github.com:8443/name',linkedin:null},{github:'https://git\nhub.com/name',linkedin:null},{github:null,linkedin:'https://www.linkedin.com/in/bad%q'}])assert.equal((await f.create({...f.input,definition:{...f.definition,links}})).response.status,400);for(const definition of [{...f.definition,publiclyPublished:true},{...f.definition,visibility:'public'},{...f.definition,schoolIssued:true},{...f.definition,content:{fr:f.definition.content.fr}},{...f.definition,content:{...f.definition.content,es:f.definition.content.en}},{...f.definition,content:{en:{...f.definition.content.en,bio:'x'.repeat(4001)}}}])assert.equal((await f.create({...f.input,definition})).response.status,400);const valid={content:f.definition.content,links:{github:null,linkedin:null},archived:false};for(const definition of [{...valid,visibility:'public'},{...valid,links:{github:'https://evil.test/name',linkedin:null}},{...valid,content:{fr:f.definition.content.fr}}])assert.equal((await f.pg.query<{v:boolean}>('SELECT public.community_profile_definition_valid($1::jsonb) v',[JSON.stringify(definition)])).rows[0].v,false);assert.equal((await f.create({...f.input,anchor:{kind:'person',id:f.bot}})).response.status,404);assert.equal((await f.create({...f.input,anchor:{kind:'class',id:f.hub}})).response.status,400);assert.equal((await f.request('community/profiles?limit=1&limit=2')).response.status,400);assert.equal((await f.pg.query('SELECT * FROM public.community_profiles')).rows.length,0);
});
check('inactive owners can retain archived drafts but cannot activate them and history cannot be overwritten or deleted',async f=>{
 const r=await f.create();assert.equal(r.response.status,201);await f.pg.query("UPDATE public.people SET status='disabled' WHERE id=$1",[f.actors.staff.person]);const path='community/profiles/'+r.body.data.id+'/change';assert.equal((await f.request(path,{expectedVersion:1,definition:r.body.data.definition})).response.status,409);assert.equal((await f.request(path,{expectedVersion:1,definition:{...r.body.data.definition,archived:true}})).response.status,200);await assert.rejects(f.pg.query('DELETE FROM public.community_profiles WHERE id=$1',[r.body.data.id]),/COMMUNITY_PROFILE_HISTORY_REQUIRED/);await assert.rejects(f.pg.exec("UPDATE public.community_profile_revisions SET definition='{}'::jsonb"),/COMMUNITY_PROFILE_EXACT_HISTORY_REQUIRED/);
});
check('a native profile and exact revision cannot commit without its same-transaction hash-bound audit receipt',async f=>{
 const id=randomUUID(),definition={...f.definition,links:{github:null,linkedin:null}};await f.pg.exec('BEGIN;SET LOCAL ROLE kavosh_runtime');try{await f.pg.query("SELECT set_config('app.academy_id',$1,true)",[f.a]);await f.pg.query("INSERT INTO public.community_profiles(academy_id,id,anchor_kind,person_id,definition,owner_snapshot,changed_by,reason) VALUES($1,$2,'person',$3,$4::jsonb,public.community_profile_owner('person',$3),$5,'No valid audit receipt')",[f.a,id,f.actors.staff.person,JSON.stringify(definition),f.actors.master.person]);await f.pg.query('INSERT INTO public.community_profile_revisions(academy_id,profile_id,version,definition) SELECT academy_id,id,version,to_jsonb(p) FROM public.community_profiles p WHERE id=$1',[id]);await assert.rejects(f.pg.exec('COMMIT'),/COMMUNITY_PROFILE_RECEIPT_REQUIRED/);}finally{await f.pg.exec('ROLLBACK');}assert.equal((await f.pg.query('SELECT * FROM public.community_profiles')).rows.length,0);assert.equal((await f.create()).response.status,201);
});
check('owner snapshots cannot be forged or reparented through native writes and foreign-school anchors stay concealed',async f=>{
 const r=await f.create();assert.equal(r.response.status,201);await assert.rejects(f.pg.query('UPDATE public.community_profiles SET version=version+1,person_id=$2 WHERE id=$1',[r.body.data.id,f.actors.manager.person]),/COMMUNITY_PROFILE_IDENTITY_CHANGED/);await assert.rejects(f.pg.query("UPDATE public.community_profiles SET version=version+1,owner_snapshot='{}'::jsonb WHERE id=$1",[r.body.data.id]),/COMMUNITY_PROFILE_OWNER_CHANGED/);assert.equal((await f.create({...f.input,anchor:{kind:'person',id:f.actors.foreignMaster.person}})).response.status,404);assert.equal((await f.create({...f.input,anchor:{kind:'hub',id:f.foreignHub}})).response.status,404);assert.equal((await f.pg.query('SELECT * FROM public.community_profile_revisions')).rows.length,1);
});
test('two quick native profile edits retain one winner and exact immutable history',{skip:!process.env.TEST_DATABASE_URL},async()=>{
 const f=await fixture();try{const r=await f.create();assert.equal(r.response.status,201);const began=performance.now(),out=await Promise.all(['First','Second'].map(displayName=>f.request('community/profiles/'+r.body.data.id+'/change',{expectedVersion:1,definition:{...r.body.data.definition,content:{en:{displayName}}}})));assert.deepEqual(out.map(r=>r.response.status).sort(),[200,409],JSON.stringify(out.map(r=>r.body)));assert.equal((await f.pg.query('SELECT * FROM public.community_profile_revisions')).rows.length,2);console.log(JSON.stringify({case:'tiny-community-profile-edit-race',elapsedMs:Math.round(performance.now()-began)}));}finally{await f.pg.close();}
});
test('actual147-to148 migration preserves existing people,roles,awards and audits without creating or publishing profiles',async()=>{
 const f=await fixture(147);try{const tables=['people','roles','role_permissions','achievement_awards','audit_events'],before=[];for(const t of tables)before.push((await f.pg.query('SELECT * FROM public.'+t+' ORDER BY 1,2')).rows);const query="SELECT oid,proowner,proacl FROM pg_proc WHERE oid=ANY(ARRAY['public.scope_contains(jsonb,jsonb)'::regprocedure,'public.report_result_context_valid(text,jsonb)'::regprocedure]) ORDER BY oid",oids=await f.pg.query(query);await f.pg.exec(await readFile(new URL('../db/migrations/148_community_profile_drafts.sql',import.meta.url),'utf8'));for(let i=0;i<tables.length;i++)assert.deepEqual((await f.pg.query('SELECT * FROM public.'+tables[i]+' ORDER BY 1,2')).rows,before[i]);assert.deepEqual(await f.pg.query(query),oids);assert.equal((await f.pg.query('SELECT * FROM public.community_profiles')).rows.length,0);await upgradeToCurrent(f.pg);assert.equal((await f.create()).response.status,201);
 }finally{await f.pg.close();}
});
check('outbox failure rolls back content,exact history and receipt so the same key can safely be retried',async f=>{
 const key=randomUUID();await f.pg.exec('REVOKE INSERT ON public.outbox_events FROM kavosh_runtime');try{assert.equal((await f.create(f.input,'master',key)).response.status,503);}finally{await f.pg.exec('GRANT INSERT ON public.outbox_events TO kavosh_runtime');}for(const table of ['community_profiles','community_profile_revisions'])assert.equal((await f.pg.query('SELECT * FROM public.'+table)).rows.length,0);assert.equal((await f.create(f.input,'master',key)).response.status,201);
});
